code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 3 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            boxes.append((min(y for y,x in cells), max(y for y,x in cells), min(x for y,x in cells), max(x for y,x in cells)))
    centers = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2 and any(r0 <= r <= r1 and c0 <= c <= c1 for r0,r1,c0,c1 in boxes):
                centers.add((r,c))
    for r,c in centers:
        for y in range(max(0,r-1), min(h,r+2)):
            for x in range(max(0,c-1), min(w,c+2)):
                if (y,x) not in centers:
                    out[y][x] = 1
    return out
